UPDATE ins_brand_info t
t.del_flag = 1
WHERE t.id = #{id}

mapper.select:
SELECT

FROM
ins_brand_info t
where 1

    and t.name = #{name}


    and t.name_en = #{nameEn}


    and t.alias = #{alias}


    and t.exclusion_words = #{exclusionWords}


    and t.code = #{code}


    and t.order_by = #{orderBy}


    and t.operator = #{operator}


    and t.create_time = #{createTime}


    and t.update_time = #{updateTime}


    and t.del_flag = #{delFlag}


    and t.img = #{img}


    and t.app_id = #{appId}

order by update_time desc
limit #{start},#{pagesize}

SELECT

FROM
ins_brand_info t
inner join ins_car_series_info car on t.code = car.brand_id
where 1

    and t.code in

        #{item}



    and (car.car_level1 in

        #{item}

    or car.car_level2 in

        #{item}

    )


    and (car.energy_type1 in

        #{item}

    or car.energy_type2 in

        #{item}

    )


    and car.name like concat('%',#{nameFilter},'%')


    and t.name = #{name}


    and t.name_en = #{nameEn}


    and t.alias = #{alias}


    and t.exclusion_words = #{exclusionWords}


    and t.code = #{code}


    and t.order_by = #{orderBy}


    and t.operator = #{operator}


    and t.create_time = #{createTime}


    and t.update_time = #{updateTime}


    and t.del_flag = #{delFlag}


    and t.img = #{img}


    and t.app_id = #{appId}

group by t.id

select ibi.id, ibi.name, ibi.create_time, ibi.update_time, sdi.item_text as competitiveTypeName, ibi.automark, sd.item_text as isCoreName, ibi.update_user as operator, sd1.item_text as statusName, ibi.status from ins_brand_info ibi left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'competitive_type' ) sdi on sdi.item_value = ibi.competitive_type left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'is_core' ) sd on sd.item_value = ibi.is_core left join (select sdi.item_text,sdi.item_value from ins_dict sd left join ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'enable_type' ) sd1 on sd1.item_value = ibi.status where 1=1
and ibi.automark in
#{item}
and ibi.name like concat('%', #{brandModel.name}, '%')
and ibi.is_core = #{brandModel.isCore}
and ibi.competitive_type = #{brandModel.competitiveType}
and ibi.status = #{brandModel.status}
and ibi.operator like concat('%', #{brandModel.operator}, '%')
order by ibi.${brandModel.order}
order by ibi.competitive_type asc,ibi.is_core desc,ibi.code asc
